//! Chest Cavity's rules with no game in them: the organs and body types
//! (`organs`, generated by `tools/import.py`), a cavity and its scores
//! (`cavity`), what the scores do to a body (`effects`), what an organ is good
//! and bad at in words (`describe`), the organs a dead mob drops (`drops`), and what a body's lungs (`breath`),
//! stomach (`food`) and bones (`damage`) do, where a random teleport lands (`teleport`), and the abilities a key sets off (`abilities`). The `engine` crate ties them to Horizon's hooks.
pub mod abilities;
pub mod breath;
pub mod cavity;
pub mod damage;
pub mod describe;
pub mod drops;
pub mod effects;
pub mod food;
pub mod organs;
pub mod teleport;
